        &self,
        config: &Arc<Config>,
        mpr: &MultiProgressReport,
        force: bool,
        dry_run: bool,
    ) -> Result<()> {
        // Skip installation for embedded plugins unless an explicit URL is being
        // installed as a filesystem override.
        if self.is_embedded() && !self.has_repo_url_override() {
            return Ok(());
        }

        let settings = Settings::try_get()?;
        if !force {
            if self.is_installed() {
                return Ok(());
            }
            if !settings.yes && self.repo_url.lock().unwrap().is_none() {
                let url = self.get_repo_url(config)?;
                let url_string = url.to_string();
                if !registry::is_trusted_plugin(self.name(), &url_string) {
                    warn!(
                        "⚠️ {} is a community-developed plugin – {}",
                        style(&self.name).blue(),
                        style(&url_string.trim_end_matches(".git")).yellow()
                    );
                    if settings.paranoid {
                        bail!(
                            "Paranoid mode is enabled, refusing to install community-developed plugin"
                        );
                    }
                    if !prompt::confirm_with_all(format!(
                        "Would you like to install {}?",
                        self.name
                    ))?
                    .is_yes()
                    {
                        Err(PluginNotInstalled(self.name.clone()))?
                    }
                }
            }
        }

        let prefix = format!("plugin:{}", style(&self.name).blue().for_stderr());
        let pr = mpr.add_with_options(&prefix, dry_run);
        if !dry_run {
            let plugin_lock = lock_file::get(&self.plugin_path, force)?;
            self.install(config, pr.as_ref()).await?;
            let plugin_type =
                PluginType::from_plugin_path(&self.plugin_path).unwrap_or(PluginType::Vfox);
            if plugin_type == PluginType::Package
                && crate::system::packages::is_builtin_manager_name(&self.name)
            {
                drop(plugin_lock);
                file::remove_all(&self.plugin_path)?;
                bail!(
                    "package plugin '{}' collides with a built-in package manager",
                    self.name
                );
            }
            install_state::add_plugin(&self.name, plugin_type).await?;
            backend::remove(&self.name);
            warn_if_env_plugin_shadows_registry(&self.name, &self.plugin_path);
        }
            install_opts
                .insert_option("bin".into(), toml::Value::String(bin.path.clone()))
                .map_err(|e| eyre!(e))?;
        }
        // The statement names every executable by path, so nothing here may
        // rename one: a tidied platform suffix would put the file somewhere the
        // statement does not point, and `link_bins` would not find it.
        if vfox_plugin {
            crate::plugins::packslip::validate_archive(&file_path)?;
        }
        install_artifact(
            &tv,
            &file_path,
            &install_opts,
            ArchiveLayout::Declared,
            Some(ctx.pr.as_ref()),
        )?;
        if vfox_plugin {
            crate::plugins::packslip::validate_layout(&tv.install_path())?;
        }
        Self::link_bins(&tv, &artifact)?;
        file::write(
            tv.install_path().join(STATEMENT_FILE),
            serde_json::to_vec_pretty(&statement)?,
        )?;
        // Completions and CLI specs the vendor keeps outside the artifact.
        if !vfox_plugin {
            crate::packslip::fetch_files(&tv, &statement, Some(&artifact), ctx.pr.as_ref()).await?;
        }
        // The pin records what was installed, so a release that failed to
        // unpack or link leaves no mark; the check above is what refuses.
        // A pin that cannot be written must not leave its artifact behind
        // either: `always_keep_install` would preserve an install whose
        // signer was never recorded, and the next release — from any signer
        // at all — would then set the project's first pin with that one
        // still in place.
        if let Err(err) = packslip_pins::record(&project, observed) {
            let _ = file::remove_all(tv.install_path());
            return Err(err);
        }
